scripts.script:
local OrionLib = loadstring(game:HttpGet(('https://raw.githubusercontent.com/shlexware/Orion/main/source')))()

local Window = OrionLib:MakeWindow({Name = "Lucky Hub", HidePremium = false, SaveConfig = true, ConfigFolder = "OrionTest"})

local Tab = Window:MakeTab({
    Name = "Lucky Block",
    Icon = "rbxassetid://4483345998",
    PremiumOnly = false
})

Tab:AddButton({
    Name = "Spawn Lucky Block",
    Callback = function()
        game:GetService("ReplicatedStorage"):WaitForChild("SpawnLuckyBlock"):FireServer()
    end      
})

Tab:AddButton({
    Name = "Spawn Diamond Block",
    Callback = function()
        game:GetService("ReplicatedStorage"):WaitForChild("SpawnDiamondBlock"):FireServer()
    end      
})

Tab:AddButton({
    Name = "Spawn Rainbow Block",
    Callback = function()
        game:GetService("ReplicatedStorage"):WaitForChild("SpawnRainbowBlock"):FireServer()
    end
})


Tab:AddButton({
    Name = "Spawn Galaxy Block",
    Callback = function()
        game:GetService("ReplicatedStorage"):WaitForChild("SpawnGalaxyBlock"):FireServer()
    end
})


Tab:AddButton({
    Name = "Spawn Void Block",
    Callback = function()
        game:GetService("ReplicatedStorage"):WaitForChild("SpawnVoidBlock"):FireServer()
    end
})

OrionLib:Init()
